scripts.alternating_sum:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    result = 0
    for i, val in enumerate(values):
        if i % 2 == 0:  # even indices (0, 2, 4, ...) are added
            result += val
        else:  # odd indices (1, 3, 5, ...) are subtracted
            result -= val
    return float(result)

